using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>Marks a level subtree as walkable floor for the floating ghost.
/// Only these surfaces feed the height probe and the follow-camera turn range.
/// Walls, furniture and NPCs must not carry this marker: when floor and wall share one mesh,
/// a wall top is indistinguishable from a real floor step.</summary>
[DisallowMultipleComponent]
[AddComponentMenu("Ghost Party/Ghost Floor Surface")]
public sealed class GhostFloorSurface : MonoBehaviour
{
    // Roots generated by the old whitebox builder, plus the first imported model name.
    static readonly string[] LegacyRootNames =
    {
        "一楼", "Level01_FirstFloor_Structure", "Level02_SecondFloor_Structure",
        "01_Slabs", "03_SunkenDanceFloor_Depth030_ThreeSteps"
    };

    // A split floor/wall model usually names the pieces 1_Floor / 1_Wall or 一楼_地板 / 一楼_墙.
    static readonly string[] FloorNameHints = { "floor", "地板", "地面" };
    static readonly string[] WallNameHints = { "墙", "wall" };

    /// <summary>Floor roots for a scene, in priority order: explicit inspector references,
    /// then objects marked with this component, then roots whose name says floor.</summary>
    public static List<Transform> ResolveRoots(Scene scene, Transform[] explicitRoots)
    {
        var roots = new List<Transform>();
        if (explicitRoots != null)
            for (int i = 0; i < explicitRoots.Length; i++)
                if (explicitRoots[i] != null) AddRoot(roots, explicitRoots[i]);
        if (roots.Count > 0) return roots;

        if (!scene.IsValid()) scene = SceneManager.GetActiveScene();
        GameObject[] sceneRoots = scene.GetRootGameObjects();

        for (int i = 0; i < sceneRoots.Length; i++)
        {
            GhostFloorSurface[] markers = sceneRoots[i].GetComponentsInChildren<GhostFloorSurface>(true);
            for (int m = 0; m < markers.Length; m++)
            {
                if (markers[m] == null || !markers[m].gameObject.activeInHierarchy) continue;
                if (!HasActiveContent(markers[m].transform)) continue;
                AddRoot(roots, markers[m].transform);
            }
        }
        if (roots.Count > 0) return roots;

        for (int i = 0; i < sceneRoots.Length; i++)
        {
            if (!sceneRoots[i].activeInHierarchy || !LooksLikeFloorName(sceneRoots[i].name)) continue;
            if (!HasActiveContent(sceneRoots[i].transform)) continue;
            AddRoot(roots, sceneRoots[i].transform);
        }
        return roots;
    }

    /// <summary>True when the name reads as a floor root and never as a wall.</summary>
    public static bool LooksLikeFloorName(string objectName)
    {
        if (string.IsNullOrEmpty(objectName)) return false;
        for (int i = 0; i < WallNameHints.Length; i++)
            if (objectName.IndexOf(WallNameHints[i], StringComparison.OrdinalIgnoreCase) >= 0) return false;
        for (int i = 0; i < LegacyRootNames.Length; i++)
        {
            string legacy = LegacyRootNames[i];
            if (objectName.Equals(legacy, StringComparison.Ordinal) ||
                objectName.StartsWith(legacy + "_", StringComparison.Ordinal) ||
                objectName.StartsWith(legacy + " ", StringComparison.Ordinal)) return true;
        }
        for (int i = 0; i < FloorNameHints.Length; i++)
            if (objectName.IndexOf(FloorNameHints[i], StringComparison.OrdinalIgnoreCase) >= 0) return true;
        return false;
    }

    /// <summary>An empty placeholder root (inactive slabs, anchors only) must not block real sources.</summary>
    static bool HasActiveContent(Transform root)
    {
        if (root == null) return false;
        Renderer[] renderers = root.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
            if (renderers[i] != null && renderers[i].enabled && renderers[i].gameObject.activeInHierarchy) return true;
        Collider[] colliders = root.GetComponentsInChildren<Collider>(true);
        for (int i = 0; i < colliders.Length; i++)
            if (colliders[i] != null && colliders[i].enabled && colliders[i].gameObject.activeInHierarchy) return true;
        return false;
    }

    static bool AddRoot(List<Transform> roots, Transform candidate)
    {
        if (candidate == null) return false;
        for (int i = 0; i < roots.Count; i++)
        {
            if (roots[i] == candidate) return false;
            // A nested marker must not turn its parent into a source twice.
            if (candidate.IsChildOf(roots[i])) return false;
            if (roots[i].IsChildOf(candidate)) { roots[i] = candidate; return false; }
        }
        roots.Add(candidate);
        return true;
    }
}
